#define MIN_CAP 8
#define GROWTH_FACTOR 2

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} DynArray;

void grow(DynArray *A) {
    if (A->size < A->capacity) return;

    size_t new_cap = (A->capacity == 0) ? MIN_CAP : A->capacity * GROWTH_FACTOR;

    int *temp = realloc(A->data, new_cap * sizeof(int));

    if (temp == NULL) { /* Handle allocation failure */ }

    A->data = temp;
    A->capacity = new_cap;
}

// Usage: grow(&my_array); my_array.data[my_array.size++] = value;
